class Solution {
public:
    bool isStrobogrammatic(string num) {
        unordered_map<char, char> mp = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
        int left = 0, right = num.size() - 1;
        while (left <= right) {
            if (!mp.count(num[left]) || mp[num[left]] != num[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
};

class Solution {
    public boolean isStrobogrammatic(String num) {
        Map<Character, Character> map = new HashMap<>();
        map.put('0', '0');
        map.put('1', '1');
        map.put('6', '9');
        map.put('8', '8');
        map.put('9', '6');
        int left = 0, right = num.length() - 1;
        while (left <= right) {
            char cl = num.charAt(left), cr = num.charAt(right);
            if (!map.containsKey(cl) || map.get(cl) != cr) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

