var isStrobogrammatic = function(num) {
    const map = { "0": "0", "1": "1", "6": "9", "8": "8", "9": "6" };
    let left = 0, right = num.length - 1;
    while (left <= right) {
        if (!map[num[left]] || map[num[left]] !== num[right]) {
            return false;
        }
        left++;
        right--;
    }
    return true;
};
